import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { 
  Card, 
  Table, 
  Input, 
  Button, 
  Tag, 
  Title, 
  Text,
  Alert,
  Space,
  DatePicker
} from '../components/BasicUI';

const Summary = () => {
  const [analysis, setAnalysis] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [filters, setFilters] = useState({
    date: '',
    level: '',
    minProbability: '',
    team: ''
  });
  const [updatingScores, setUpdatingScores] = useState(false);

  const fetchAnalysis = async (autoUpdate = false) => {
    setLoading(true);
    setError(null);
    try {
      const params = new URLSearchParams();
      if (filters.date) params.append('date', filters.date);
      if (filters.level) params.append('level', filters.level);
      if (filters.minProbability) params.append('minProbability', filters.minProbability);
      if (filters.team) params.append('team', filters.team);
      if (autoUpdate) params.append('autoUpdate', 'true');

      const response = await axios.get(`/api/games/summary?${params.toString()}`);
      setAnalysis(response.data.data || []);
    } catch (err) {
      setError('Error al cargar el resumen: ' + (err.response?.data?.message || err.message));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    // Cargar con actualización automática la primera vez
    fetchAnalysis(true);
  }, []);

  const handleFilterChange = (field, value) => {
    setFilters(prev => ({ ...prev, [field]: value }));
  };

  const handleApplyFilters = () => {
    fetchAnalysis();
  };

  const handleClearFilters = () => {
    setFilters({
      date: '',
      level: '',
      minProbability: '',
      team: ''
    });
  };

  const handleUpdateScores = async () => {
    setUpdatingScores(true);
    setError(null);
    try {
      // Obtener fechas únicas de los análisis actuales
      const dates = [...new Set(analysis.map(a => a.game_date))];

      for (const date of dates) {
        await axios.get(`/api/update-scores/${date}`);
      }

      // Recargar los datos después de actualizar
      await fetchAnalysis();

      // Mostrar mensaje de éxito
      setError(null);
    } catch (err) {
      setError('Error al actualizar scores: ' + (err.response?.data?.message || err.message));
    } finally {
      setUpdatingScores(false);
    }
  };

  const getLevelColor = (level) => {
    switch (level) {
      case 'Diamond': return 'red';
      case 'Exclusive': return 'orange';
      case 'VIP': return 'blue';
      default: return 'default';
    }
  };

  // Función para determinar el resultado del partido
  const getGameResult = (record) => {
    // Verificar si el partido está finalizado
    const isFinal = record.status === 'final' || record.status === 'completed';

    // Mostrar resultado si hay scores disponibles (incluyendo 0) o si el partido está finalizado
    if ((record.home_score !== null && record.away_score !== null && 
         record.home_score !== undefined && record.away_score !== undefined) || isFinal) {

      // Si hay scores, usar la lógica normal
      if (record.home_score !== null && record.away_score !== null && 
          record.home_score !== undefined && record.away_score !== undefined) {
        const homeWon = record.home_score > record.away_score;
        const isTie = record.home_score === record.away_score;

        if (isTie) {
          return {
            home: 'Empate',
            away: 'Empate',
            scores: `${record.away_score} - ${record.home_score}`
          };
        }

        return {
          home: homeWon ? 'Ganador' : 'Perdedor',
          away: homeWon ? 'Perdedor' : 'Ganador',
          scores: `${record.away_score} - ${record.home_score}`
        };
      }

      // Si el partido está finalizado pero no hay scores, mostrar como "Finalizado"
      if (isFinal) {
        return {
          home: 'Finalizado',
          away: 'Finalizado',
          scores: 'Sin scores'
        };
      }
    }

    return { home: null, away: null, scores: null };
  };

  const columns = [
    {
      title: 'Fecha',
      dataIndex: 'game_date',
      render: (date, record) => (
        <div>
          <div>{new Date(date).toLocaleDateString('es-ES')}</div>
          <div style={{ 
            fontSize: '10px', 
            color: record.status === 'final' ? '#52c41a' : 
                   record.status === 'live' ? '#ff4d4f' : '#666',
            fontWeight: 'bold'
          }}>
            {record.status === 'final' ? 'Finalizado' : 
             record.status === 'live' ? 'En vivo' : 
             record.status === 'scheduled' ? 'Programado' : record.status}
          </div>
        </div>
      )
    },
    {
      title: 'Visitante',
      dataIndex: 'away_team_name',
      render: (text, record) => {
        const result = getGameResult(record);
        return (
          <div>
            <div>{text}</div>
            {result.away && (
              <div style={{ 
                fontSize: '12px', 
                color: result.away === 'Ganador' ? '#52c41a' : 
                       result.away === 'Perdedor' ? '#ff4d4f' : 
                       result.away === 'Empate' ? '#1890ff' : '#666',
                fontWeight: 'bold'
              }}>
                {result.away}
              </div>
            )}
          </div>
        );
      }
    },
    {
      title: 'Local',
      dataIndex: 'home_team_name',
      render: (text, record) => {
        const result = getGameResult(record);
        return (
          <div>
            <div>{text}</div>
            {result.home && (
              <div style={{ 
                fontSize: '12px', 
                color: result.home === 'Ganador' ? '#52c41a' : 
                       result.home === 'Perdedor' ? '#ff4d4f' : 
                       result.home === 'Empate' ? '#1890ff' : '#666',
                fontWeight: 'bold'
              }}>
                {result.home}
              </div>
            )}
          </div>
        );
      }
    },
    {
      title: 'Resultado',
      dataIndex: 'result',
      render: (text, record) => {
        const result = getGameResult(record);
        if (result.scores) {
          return (
            <div style={{ 
              fontSize: '14px', 
              fontWeight: 'bold',
              color: '#1890ff'
            }}>
              {result.scores}
            </div>
          );
        }
        return <span style={{ color: '#999' }}>-</span>;
      }
    },
    {
      title: 'Prob. Visitante',
      dataIndex: 'away_probability',
      render: (prob) => `${(prob * 100).toFixed(1)}%`
    },
    {
      title: 'Prob. Local',
      dataIndex: 'home_probability',
      render: (prob) => `${(prob * 100).toFixed(1)}%`
    },
    {
      title: 'Nivel',
      dataIndex: 'level',
      render: (level) => (
        <Tag color={getLevelColor(level)}>
          {level}
        </Tag>
      )
    }
  ];

  const stats = {
    total: analysis.length,
    diamond: analysis.filter(a => a.level === 'Diamond').length,
    exclusive: analysis.filter(a => a.level === 'Exclusive').length,
    vip: analysis.filter(a => a.level === 'VIP').length,
    withResults: analysis.filter(a => {
      const result = getGameResult(a);
      return result.scores !== null;
    }).length,
    finalGames: analysis.filter(a => a.status === 'final' || a.status === 'completed').length
  };

  return (
    <div className="summary-page">
      <Title level={1}>Resumen Avanzado</Title>

      <Space direction="vertical" size="large">
        <Card title="Filtros">
          <Space wrap>
            <div>
              <Text>Fecha:</Text>
              <DatePicker
                value={filters.date}
                onChange={(e) => handleFilterChange('date', e.target.value)}
                placeholder="YYYY-MM-DD"
              />
            </div>

            <div>
              <Text>Nivel:</Text>
              <select 
                value={filters.level} 
                onChange={(e) => handleFilterChange('level', e.target.value)}
                className="basic-input"
              >
                <option value="">Todos</option>
                <option value="Diamond">Diamond</option>
                <option value="Exclusive">Exclusive</option>
                <option value="VIP">VIP</option>
              </select>
            </div>

            <div>
              <Text>Prob. Mínima (%):</Text>
              <Input
                type="number"
                value={filters.minProbability}
                onChange={(e) => handleFilterChange('minProbability', e.target.value)}
                placeholder="50"
                min="0"
                max="100"
              />
            </div>

            <div>
              <Text>Equipo:</Text>
              <Input
                value={filters.team}
                onChange={(e) => handleFilterChange('team', e.target.value)}
                placeholder="Buscar equipo..."
              />
            </div>

            <Button type="primary" onClick={handleApplyFilters} loading={loading}>
              Aplicar
            </Button>

            <Button onClick={handleClearFilters}>
              Limpiar
            </Button>

            <Button 
              type="default" 
              onClick={handleUpdateScores} 
              loading={updatingScores}
              style={{ backgroundColor: '#52c41a', borderColor: '#52c41a', color: 'white' }}
            >
              Actualizar Scores
            </Button>
          </Space>
        </Card>

        <Card title="Estadísticas">
          <Space wrap>
            <div className="stat-item">
              <Text strong>Total: {stats.total}</Text>
            </div>
            <div className="stat-item">
              <Text strong>Diamond: {stats.diamond}</Text>
            </div>
            <div className="stat-item">
              <Text strong>Exclusive: {stats.exclusive}</Text>
            </div>
            <div className="stat-item">
              <Text strong>VIP: {stats.vip}</Text>
            </div>
            <div className="stat-item">
              <Text strong style={{ color: stats.withResults > 0 ? '#52c41a' : '#666' }}>
                Con Resultados: {stats.withResults}
              </Text>
            </div>
            <div className="stat-item">
              <Text strong style={{ color: stats.finalGames > 0 ? '#1890ff' : '#666' }}>
                Finalizados: {stats.finalGames}
              </Text>
            </div>
          </Space>
        </Card>

        {error && (
          <Alert
            type="error"
            message="Error"
            description={error}
          />
        )}

        <Card title="Resultados Filtrados">
          <Table
            columns={columns}
            dataSource={analysis}
            loading={loading}
          />
        </Card>

        {analysis.length === 0 && !loading && (
          <Alert
            type="info"
            message="No hay resultados"
            description="No se encontraron análisis que coincidan con los filtros aplicados."
          />
        )}
      </Space>
    </div>
  );
};

export default Summary;
